import React, { useEffect, useId, useState } from "react"

import { Checkbox, Icon, Select, Toggle } from "../ui"
import { getCompany } from "../../data/companies"

/**
 * BreakoutFilterRail — the control column of the /breakouts board.
 *
 * Two stacked panels: the filter set and the saved-screen list. The component
 * is fully controlled; it owns no filter state. The only local state is the
 * text of the two price fields, which has to be local so a half-typed value
 * ("1." or "-") survives a keystroke instead of being round-tripped through
 * Number() and snapping back.
 *
 * Every control here really narrows the table — `filterRows` below is the same
 * predicate the page runs, and the count in the rail is its result. A filter
 * panel that looked live but changed nothing would be worse than none.
 *
 * SSR: no window, document or localStorage at module scope or during render.
 * The two effects only re-sync the price drafts when the parent replaces them.
 */

export const DEFAULT_BREAKOUT_FILTERS = {
  priceMin: 1,
  priceMax: 20,
  marketCapMin: 100e6,
  avgVolumeMin: 500e3,
  /*
   * 1.0x, not the 2.0x the brief suggested. RVOL across the 24 generated rows
   * spans 0.82x-1.39x (mean 1.05x), because the candle generator scales every
   * session's volume to the ticker's own average — so a 2.0x floor matches
   * nothing and the screen opens empty. The higher options remain selectable;
   * they simply return no rows until the generator models unusual-volume
   * sessions. Better an honest default than a fabricated volume spike.
   */
  rvolMin: 1.0,
  exchanges: { NASDAQ: true, NYSE: true, AMEX: true },
  excludeOtc: false,
  requireNews: false,
  confirmedOnly: false,
}

/* Option values are raw dollars, raw shares and plain multiples, so the filter
   state never carries a string that has to be re-parsed downstream. */
const MARKET_CAP_OPTIONS = [
  { label: "$50M", value: 50e6 },
  { label: "$100M", value: 100e6 },
  { label: "$500M", value: 500e6 },
  { label: "$1B", value: 1e9 },
  { label: "$10B", value: 10e9 },
]

const AVG_VOLUME_OPTIONS = [
  { label: "100K", value: 100e3 },
  { label: "500K", value: 500e3 },
  { label: "1M", value: 1e6 },
  { label: "5M", value: 5e6 },
  { label: "20M", value: 20e6 },
]

const RVOL_OPTIONS = [
  { label: "1.0x", value: 1 },
  { label: "1.5x", value: 1.5 },
  { label: "2.0x", value: 2 },
  { label: "3.0x", value: 3 },
  { label: "4.0x", value: 4 },
]

const EXCHANGES = ["NASDAQ", "NYSE", "AMEX"]

/* What "exclude OTC" keeps: a real exchange listing. */
const LISTED = ["NASDAQ", "NYSE", "AMEX"]

const TOGGLES = [
  { key: "excludeOtc", label: "Exclude OTC" },
  { key: "requireNews", label: "Require news" },
  { key: "confirmedOnly", label: "Show only confirmed" },
]

/* "Confirmed" is four of the six checklist items — a majority, stated here once
   so the rail and the table cannot drift apart on what the word means. */
const CONFIRMED_MIN = 4

// Geometry only; no colour lives in a JS style object.
const FULL_WIDTH = { width: "100%" }

/* --------------------------------------------------------------------------
   Number helpers. Every one of them returns either a finite number or null —
   NaN must never reach the filter state or a comparison.
   -------------------------------------------------------------------------- */

function num(value) {
  return Number.isFinite(value) ? value : null
}

/** A filter bound: a finite number, or null meaning "no bound". */
function toBound(value) {
  return Number.isFinite(value) ? value : null
}

/** Parse a text field into a bound. Empty or non-numeric becomes null. */
function parseBound(text) {
  const raw = String(text === null || text === undefined ? "" : text).trim()
  if (raw === "") return null
  const parsed = Number(raw)
  return Number.isFinite(parsed) ? parsed : null
}

function boundToText(value) {
  return Number.isFinite(value) ? String(value) : ""
}

function sameBound(a, b) {
  if (a === null && b === null) return true
  if (a === null || b === null) return false
  return a === b
}

/** Map a native select's string value back onto its typed option value. */
function pickValue(options, raw) {
  const hit = options.find(option => String(option.value) === String(raw))
  return hit ? hit.value : null
}

/* --------------------------------------------------------------------------
   filterRows — pure, no React, no mutation. The page uses it directly.
   -------------------------------------------------------------------------- */

/**
 * Narrow the breakout rows to those matching `filters`.
 *
 * Price, RVOL, news and the checklist come off the row; market cap, average
 * volume and the exchange come off the company record, so each row is joined to
 * getCompany(row.symbol) first. A row with no company record is dropped rather
 * than waved through unchecked.
 *
 * Returns a new array. The input is never mutated.
 */
export function filterRows(rows, filters) {
  if (!Array.isArray(rows)) return []

  const f = filters || DEFAULT_BREAKOUT_FILTERS
  const priceMin = toBound(f.priceMin)
  const priceMax = toBound(f.priceMax)
  const capMin = toBound(f.marketCapMin)
  const volumeMin = toBound(f.avgVolumeMin)
  const rvolMin = toBound(f.rvolMin)
  const exchanges = f.exchanges && typeof f.exchanges === "object" ? f.exchanges : null

  return rows.filter(row => {
    if (!row) return false

    const company = getCompany(row.symbol)
    if (!company) return false

    // Price, within whichever bounds are set.
    if (priceMin !== null || priceMax !== null) {
      const price = num(row.price)
      if (price === null) return false
      if (priceMin !== null && price < priceMin) return false
      if (priceMax !== null && price > priceMax) return false
    }

    if (capMin !== null) {
      const cap = num(company.marketCap)
      if (cap === null || cap < capMin) return false
    }

    if (volumeMin !== null) {
      const avg = num(company.avgVolume)
      if (avg === null || avg < volumeMin) return false
    }

    // A missing RVOL fails the minimum rather than passing silently — an
    // unmeasured row is not a confirmed one.
    if (rvolMin !== null) {
      const rvol = num(row.rvol)
      if (rvol === null || rvol < rvolMin) return false
    }

    // Exchange. NOTE: the AMEX box is wired and functional, but none of the 14
    // companies in this dataset is listed on AMEX, so it currently matches
    // nothing — it narrows only in combination with the other two.
    if (exchanges && !exchanges[company.exchange]) return false

    if (f.excludeOtc && LISTED.indexOf(company.exchange) === -1) return false

    if (f.requireNews) {
      const news = row.subScores ? num(row.subScores.news) : null
      if (news === null || news <= 0) return false
    }

    if (f.confirmedOnly) {
      const list = Array.isArray(row.checklist) ? row.checklist : []
      let passed = 0
      for (let i = 0; i < list.length; i += 1) {
        if (list[i] && list[i].passed) passed += 1
      }
      if (passed < CONFIRMED_MIN) return false
    }

    return true
  })
}

/* --------------------------------------------------------------------------
   Saved screens. The shape is read defensively so the page can pass either a
   screen object or its id as `activeScreen`.
   -------------------------------------------------------------------------- */

function screenId(screen) {
  if (!screen || typeof screen !== "object") return null
  if (screen.id !== undefined && screen.id !== null) return String(screen.id)
  if (screen.name !== undefined && screen.name !== null) return String(screen.name)
  return null
}

function isActiveScreen(screen, activeScreen) {
  if (!screen || !activeScreen) return false
  if (screen === activeScreen) return true
  const active = typeof activeScreen === "object" ? screenId(activeScreen) : String(activeScreen)
  const id = screenId(screen)
  return active !== null && id !== null && active === id
}

/* --------------------------------------------------------------------------
   Component
   -------------------------------------------------------------------------- */

export default function BreakoutFilterRail({
  filters,
  onChange,
  onRun,
  onReset,
  matchCount = 0,
  total = 24,
  savedScreens,
  activeScreen,
  onSelectScreen,
}) {
  const f = filters || DEFAULT_BREAKOUT_FILTERS

  const baseId = useId()
  const filterTitleId = "bfilter-title-" + baseId
  const priceLabelId = "bfilter-price-" + baseId
  const exchangeLabelId = "bfilter-exchange-" + baseId
  const savedTitleId = "saved-title-" + baseId

  // The price fields keep their own text so an in-progress value is not
  // rewritten under the cursor. The filter state still only ever receives a
  // finite number or null.
  const [priceMinText, setPriceMinText] = useState(() => boundToText(f.priceMin))
  const [priceMaxText, setPriceMaxText] = useState(() => boundToText(f.priceMax))

  const incomingMin = toBound(f.priceMin)
  const incomingMax = toBound(f.priceMax)

  // Re-sync only when the parent has moved the value somewhere the draft does
  // not already describe — a reset, or a saved screen being loaded.
  useEffect(() => {
    setPriceMinText(prev =>
      sameBound(parseBound(prev), incomingMin) ? prev : boundToText(incomingMin)
    )
  }, [incomingMin])

  useEffect(() => {
    setPriceMaxText(prev =>
      sameBound(parseBound(prev), incomingMax) ? prev : boundToText(incomingMax)
    )
  }, [incomingMax])

  function set(key, value) {
    if (typeof onChange === "function") onChange({ ...f, [key]: value })
  }

  function setExchange(name, checked) {
    const current = f.exchanges && typeof f.exchanges === "object" ? f.exchanges : {}
    set("exchanges", { ...current, [name]: checked })
  }

  function handlePriceMin(event) {
    const text = event.target.value
    setPriceMinText(text)
    set("priceMin", parseBound(text))
  }

  function handlePriceMax(event) {
    const text = event.target.value
    setPriceMaxText(text)
    set("priceMax", parseBound(text))
  }

  function handleSelect(key, options) {
    return event => {
      const next = pickValue(options, event.target.value)
      // An unrecognised value is discarded rather than written as null.
      if (next !== null) set(key, next)
    }
  }

  function handleScreen(screen) {
    if (typeof onSelectScreen === "function") onSelectScreen(screen)
  }

  const screens = Array.isArray(savedScreens) ? savedScreens : []

  return (
    <>
      <section className="bfilter" aria-labelledby={filterTitleId}>
        <div className="bfilter__head">
          <h2 className="bfilter__title" id={filterTitleId}>
            Breakout filters
          </h2>
        </div>

        <div className="bfilter__body">
          {/* 1 — price range */}
          <div className="bfilter__group" role="group" aria-labelledby={priceLabelId}>
            <span className="bfilter__label" id={priceLabelId}>
              Price range
            </span>
            <div className="bfilter__range">
              <input
                className="bfilter__range-input"
                id={"bfilter-price-min-" + baseId}
                type="number"
                inputMode="decimal"
                min="0"
                step="0.5"
                placeholder="Min"
                aria-label="Minimum price"
                value={priceMinText}
                onChange={handlePriceMin}
              />
              <span className="bfilter__range-sep" aria-hidden="true">
                –
              </span>
              <input
                className="bfilter__range-input"
                id={"bfilter-price-max-" + baseId}
                type="number"
                inputMode="decimal"
                min="0"
                step="0.5"
                placeholder="Max"
                aria-label="Maximum price"
                value={priceMaxText}
                onChange={handlePriceMax}
              />
            </div>
          </div>

          {/* 2 — thresholds */}
          <div className="bfilter__group">
            <Select
              id={"bfilter-cap-" + baseId}
              label="Market cap (min)"
              options={MARKET_CAP_OPTIONS}
              value={f.marketCapMin}
              onChange={handleSelect("marketCapMin", MARKET_CAP_OPTIONS)}
            />
            <Select
              id={"bfilter-vol-" + baseId}
              label="Average daily volume (min)"
              options={AVG_VOLUME_OPTIONS}
              value={f.avgVolumeMin}
              onChange={handleSelect("avgVolumeMin", AVG_VOLUME_OPTIONS)}
            />
            <Select
              id={"bfilter-rvol-" + baseId}
              label="Relative volume (min)"
              options={RVOL_OPTIONS}
              value={f.rvolMin}
              onChange={handleSelect("rvolMin", RVOL_OPTIONS)}
            />
          </div>

          {/* 3 — exchanges */}
          <div className="bfilter__group" role="group" aria-labelledby={exchangeLabelId}>
            <span className="bfilter__label" id={exchangeLabelId}>
              Exchange
            </span>
            <div className="bfilter__checks">
              {EXCHANGES.map(name => (
                <Checkbox
                  key={name}
                  id={"bfilter-ex-" + baseId + "-" + name}
                  label={name}
                  checked={!!(f.exchanges && f.exchanges[name])}
                  onChange={event => setExchange(name, event.target.checked)}
                />
              ))}
            </div>
          </div>

          {/* 4 — refinements */}
          <div className="bfilter__toggles">
            {TOGGLES.map(toggle => (
              <Toggle
                key={toggle.key}
                id={"bfilter-tg-" + baseId + "-" + toggle.key}
                label={toggle.label}
                checked={!!f[toggle.key]}
                onChange={event => set(toggle.key, event.target.checked)}
              />
            ))}
          </div>

          {/* 5 — the live result of the filters above, announced when it moves */}
          <p className="bfilter__count" aria-live="polite">
            <strong>{matchCount}</strong> of {total} breakouts match
          </p>

          {/*
            6 — every control above already applies immediately, so this button
            re-runs the scan rather than being the thing that makes it happen.
          */}
          <div className="bfilter__actions">
            <button type="button" className="btn btn--primary" style={FULL_WIDTH} onClick={onRun}>
              Run breakout scan
            </button>
            <button type="button" className="bfilter__reset" onClick={onReset}>
              Reset filters
            </button>
          </div>
        </div>
      </section>

      <section className="saved" aria-labelledby={savedTitleId}>
        <div className="saved__head">
          <h2 className="saved__title" id={savedTitleId}>
            Saved screens
          </h2>
        </div>

        {/*
          Intentionally inert in the prototype: there is no store behind saved
          screens, so this is a visual affordance for the future save flow. It
          carries no handler rather than faking persistence.
        */}
        <button type="button" className="saved__add">
          <Icon name="plus" size={14} className="btn__icon" />
          Save current screen
        </button>

        <div className="saved__list">
          {screens.length === 0 ? (
            <p className="saved__meta">No saved screens yet.</p>
          ) : (
            screens.map((screen, index) => {
              const active = isActiveScreen(screen, activeScreen)
              const name = (screen && (screen.name || screen.label)) || "Untitled screen"
              const meta = screen ? screen.meta : null

              return (
                <button
                  key={screenId(screen) || "screen-" + index}
                  type="button"
                  className={active ? "saved__item saved__item--active" : "saved__item"}
                  aria-pressed={active}
                  onClick={() => handleScreen(screen)}
                >
                  <span className="saved__name">{name}</span>
                  {meta ? <span className="saved__meta">{meta}</span> : null}
                </button>
              )
            })
          )}
        </div>
      </section>
    </>
  )
}
