import React, { useEffect, useRef } from "react"

/**
 * The /breakouts detail chart: real candlesticks with a dashed line at the
 * breakout level, tagged on the right edge.
 *
 * GATSBY CONSTRAINT: lightweight-charts touches `window` at import time and
 * Gatsby renders to HTML in Node at build, so the library is loaded with a
 * dynamic `await import()` INSIDE useEffect. Same guard as every other chart here.
 *
 * The level is drawn with the library's own price line rather than an overlaid
 * div, so it stays pinned to the price scale when the series or timeframe
 * changes, and its axis tag lines up exactly with the value.
 */

function readToken(styles, name) {
  const value = styles.getPropertyValue(name)
  return value && value.trim() ? value.trim() : undefined
}

function defined(object) {
  const out = {}
  for (const key of Object.keys(object)) {
    if (object[key] !== undefined) out[key] = object[key]
  }
  return out
}

export default function LevelChart({ candles = [], level = null, height = 200 }) {
  const containerRef = useRef(null)

  useEffect(() => {
    let chart = null
    let observer = null
    let cancelled = false

    async function mount() {
      const container = containerRef.current
      if (!container || !candles.length) return

      const { createChart, LineStyle } = await import("lightweight-charts")
      if (cancelled || !containerRef.current) return

      const styles = window.getComputedStyle(document.documentElement)
      const up = readToken(styles, "--chart-up")
      const down = readToken(styles, "--chart-down")

      chart = createChart(container, {
        width: container.clientWidth,
        height,
        layout: {
          background: defined({ color: readToken(styles, "--surface") }),
          ...defined({
            textColor: readToken(styles, "--chart-axis"),
            fontFamily: readToken(styles, "--font-ui"),
          }),
          fontSize: 10,
          attributionLogo: false,
        },
        grid: {
          vertLines: { visible: false },
          horzLines: {
            ...defined({ color: readToken(styles, "--chart-grid") }),
            style: LineStyle.Solid,
          },
        },
        rightPriceScale: { borderVisible: false, scaleMargins: { top: 0.15, bottom: 0.15 } },
        timeScale: { borderVisible: false, timeVisible: true, secondsVisible: false },
        crosshair: {
          vertLine: {
            ...defined({ color: readToken(styles, "--chart-crosshair") }),
            width: 1,
            style: LineStyle.Dashed,
          },
          horzLine: {
            ...defined({ color: readToken(styles, "--chart-crosshair") }),
            width: 1,
            style: LineStyle.Dashed,
          },
        },
        handleScale: false,
        handleScroll: false,
      })

      const series = chart.addCandlestickSeries({
        ...defined({
          upColor: up,
          downColor: down,
          borderUpColor: up,
          borderDownColor: down,
          wickUpColor: up,
          wickDownColor: down,
        }),
        priceLineVisible: false,
      })
      series.setData(candles)

      if (Number.isFinite(level)) {
        series.createPriceLine({
          price: level,
          ...defined({ color: readToken(styles, "--accent") }),
          lineWidth: 1,
          lineStyle: LineStyle.Dashed,
          axisLabelVisible: true,
          title: "Breakout",
        })
      }

      chart.timeScale().fitContent()

      if (typeof ResizeObserver !== "undefined") {
        observer = new ResizeObserver(entries => {
          if (!chart || !entries.length) return
          chart.applyOptions({ width: Math.floor(entries[0].contentRect.width) })
          chart.timeScale().fitContent()
        })
        observer.observe(container)
      }
    }

    mount()

    return () => {
      cancelled = true
      if (observer) observer.disconnect()
      if (chart) chart.remove()
    }
  }, [candles, level, height])

  return <div className="level-chart" ref={containerRef} style={{ height: height + "px" }} />
}
